/* Moov’On — portail entreprise de démonstration, données locales uniquement. */
(() => {
  'use strict';
  const root = document.getElementById('admin-root');
  const modalRoot = document.getElementById('modal-root');
  const icons = {
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    palette:'<path d="M12 3a9 9 0 1 0 0 18h1.5a2 2 0 0 0 1.4-3.4 1.5 1.5 0 0 1 1.1-2.6h2a3 3 0 0 0 3-3 9 9 0 0 0-9-9Z"/><circle cx="7" cy="11" r=".6"/><circle cx="10" cy="7" r=".6"/><circle cx="15" cy="7" r=".6"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.9M15 3.1a4 4 0 0 1 0 7.8"/><circle cx="9" cy="7" r="4"/>',
    teams:'<rect x="8" y="3" width="8" height="5" rx="1"/><rect x="2" y="16" width="8" height="5" rx="1"/><rect x="14" y="16" width="8" height="5" rx="1"/><path d="M12 8v4M6 16v-4h12v4"/>',
    stories:'<circle cx="12" cy="12" r="9" stroke-dasharray="5 4"/><path d="m10 8 6 4-6 4V8Z"/>',
    presentation:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v5m-4 0h8m-1-14 4 2.5-4 2.5Z"/>',
    arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
    external:'<path d="M15 3h6v6m-9 3 9-9M9 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-4"/>',
    logout:'<path d="M9 5H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h4m7-14 5 7-5 7m-5-7h10"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',
    trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v6m4-6v6"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
    reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',
    mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
    spark:''
  };
  const titles = {campaigns:'Campagnes solidaires',associations:'Associations & missions',rules:'Conversion & énergie',overview:'Vue d’ensemble',branding:'Identité visuelle',people:'Collaborateurs',teams:'Équipes',moderation:'Stories & modération',presentation:'Présentation',enterprises:'Entreprises clientes'};
  let page = Object.hasOwn(titles,location.hash.slice(1)) ? location.hash.slice(1) : 'overview';
  let selectedOrgId = '', brandDraft = null, teamDraft = [], peopleSearch = '', peopleFilter = 'all';
  let toastTimer, mutating = false, lastFocus = null, renderedIdentity = '';
  let associationDraft=null, catalogueFilter='', campaignDraft=null;
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = name => name==='spark' ? Energy.icon : `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.grid}</svg>`;
  const initial = name => String(name || '?').trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const hex = (value,fallback='#1543B7') => /^#[a-f\d]{6}$/i.test(value || '') ? value : fallback;
  const luminance = color => hex(color).slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);
  const contrastInk = color => luminance(color)>.179 ? '#182237' : '#FFFFFF';
  const img = value => typeof value === 'string' && /^data:image\/(png|jpeg|webp);base64,[a-z\d+/=]+$/i.test(value) ? value : '';
  const fmt = n => Number(n || 0).toLocaleString('fr-FR');
  const date = n => new Date(n).toLocaleDateString('fr-FR',{day:'numeric',month:'short'});
  const fullDate = n => new Date(n).toLocaleString('fr-FR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});
  function current() { return window.Demo?.current() || null; }
  function activeOrg() { const session = current(); return session ? Demo.org(selectedOrgId || session.org.id) || session.org : null; }
  function members() { return Demo.users(activeOrg().id).filter(user=>user.role!=='platform'); }
  function mark(org,cls='org-mark') { return `<span class="${cls}">${img(org.logo) ? `<img src="${img(org.logo)}" alt="Logo ${esc(org.name)}">` : esc(initial(org.shortName || org.name))}</span>`; }
  function statusPill(status) { return `<span class="pill ${status==='active'?'green':status==='invited'?'orange':'red'}">${status==='active'?'Actif':status==='invited'?'Invité':'Suspendu'}</span>`; }
  function roleLabel(role) { return role==='platform'?'Opérateur Moov’On':role==='admin'?'Administrateur':'Collaborateur'; }
  function mutate(fn) { mutating = true; try { return fn(); } finally { mutating = false; } }
  function selectOrg(orgId) {const session=current();if(session?.user.role==='platform'&&session.org.id!==orgId)mutate(()=>Demo.login({email:session.user.email,orgId}));selectedOrgId=orgId;}
  function notify(message,error=false) { const box = document.getElementById('toast'); box.textContent=message; box.className=`toast visible${error?' error':''}`; clearTimeout(toastTimer); toastTimer=setTimeout(()=>box.classList.remove('visible'),4200); }
  function appStats(orgId) {
    try { const data=JSON.parse(localStorage.getItem(`moovon:app:v2:${orgId}`)||'{}'); return {energy:Number(data.corpEnergy)||0,posts:data.posts?.length||0,donated:Object.values(data.profiles||{}).reduce((sum,p)=>sum+Object.values(p.given||{}).reduce((a,b)=>a+(Number(b)||0),0),0)}; }
    catch {return {energy:0,posts:0,donated:0};}
  }
  function protectedPage(error='') {
    root.innerHTML=`<main class="access-page"><section class="access-card"><span class="brand-word">moov<span>’on</span></span><span class="eyebrow">Portail entreprise</span><h1 style="margin-top:12px">Un espace pour faire<br>bouger votre collectif.</h1><p>${esc(error || 'Connectez-vous avec un compte administrateur pour personnaliser votre espace et accompagner vos équipes.')}</p><a class="button primary" href="./index.html?portal=1">Se connecter au portail ${icon('arrow')}</a><p class="small" style="margin-bottom:0">Démonstration · données locales</p></section></main>`;
    closeModal();
  }
  function render(resetDraft=true) {
    const session=current();
    if (!session || !Demo.canAdmin()) { protectedPage(session?'Cet espace est réservé aux administrateurs. Retrouvez vos activités et vos stories dans l’application.':''); return; }
    if (['enterprises','associations','rules'].includes(page)&&session.user.role!=='platform') page='overview';
    if (session.user.role!=='platform') selectedOrgId=session.org.id;
    const org=activeOrg();
    if (!org) {protectedPage('Aucune entreprise accessible.');return;}
    renderedIdentity=[session.user.id,session.user.role,session.org.id].join(':');
    document.documentElement.style.setProperty('--brand',hex(org.color));
    document.documentElement.style.setProperty('--accent',hex(org.accent,'#7254CC'));
    document.documentElement.style.setProperty('--brand-ink',contrastInk(org.color));
    document.documentElement.style.setProperty('--brand-readable',luminance(org.color)>.35?'#253D6A':hex(org.color));
    document.title=`${titles[page]} · ${org.name} · Moov’On`;
    if(resetDraft){brandDraft={...org};teamDraft=[...(org.teams||[])];}
    root.innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><a href="./index.html" class="brand-word" aria-label="Moov’On, application">moov<span>’on</span></a><div class="brand-descriptor">Espace entreprise</div><div><div class="org-switch">${mark(org)}<div><div class="org-name">${esc(org.name)}</div><div class="org-sub">${session.user.role==='platform'?'Administration Moov’On':'Votre espace privé'}</div></div></div>${session.user.role==='platform'?`<label class="sr-only" for="org-selector">Entreprise à administrer</label><select id="org-selector" class="platform-select" style="margin:-14px 0 15px">${Demo.orgs().map(o=>`<option value="${esc(o.id)}" ${o.id===org.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`:''}</div><nav aria-label="Navigation entreprise">${[['overview','grid'],['campaigns','shield'],['branding','palette'],['people','users'],['teams','teams'],['moderation','stories']].map(([id,ico])=>nav(id,ico)).join('')}<div class="nav-label">Votre démonstration</div>${nav('presentation','presentation')}${session.user.role==='platform'?'<div class="nav-label">CRM Moov’On</div>'+nav('associations','shield')+nav('rules','spark')+nav('enterprises','teams'):''}</nav><div class="sidebar-bottom"><a class="sidebar-link" href="./index.html">${icon('external')} Voir l’application</a><div class="demo-label">Démonstration · données locales</div></div></aside><div class="main"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" type="button" data-action="menu" aria-label="Ouvrir le menu" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Portail entreprise</span><span aria-hidden="true">/</span><strong>${titles[page]}</strong></div></div><div class="account"><span class="avatar">${esc(initial(session.user.name))}</span><div><div class="account-name">${esc(session.user.name)}</div><div class="account-role">${roleLabel(session.user.role)}</div></div><button class="icon-button" data-action="logout" title="Se déconnecter" aria-label="Se déconnecter">${icon('logout')}</button></div></header><main class="content" id="main-content">${renderPage()}</main></div></div>`;
    document.getElementById('phone-preview')?.style.setProperty('--preview-ink',contrastInk(org.color));
  }
  function nav(id,ico) { return `<button class="nav-button ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ico)}${titles[id]}</button>`; }
  function heading(title,subtitle,action='') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
  function stat(label,value,foot,ico) {return `<div class="stat"><div class="stat-heading">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${fmt(value)}</div><div class="stat-foot">${foot}</div></div>`;}
  function renderPage() {return ({overview:overviewPage,branding:brandingPage,people:peoplePage,teams:teamsPage,moderation:moderationPage,presentation:presentationPage,enterprises:enterprisesPage,campaigns:campaignsPage,associations:associationsPage,rules:rulesPage})[page]();}
  function overviewPage() {return impactOverview();}
  function quick(ico,title,description,dest) {return `<div class="quick-item"><span class="stat-icon">${icon(ico)}</span><div><strong>${title}</strong><p>${description}</p></div><button class="icon-button" data-page="${dest}" aria-label="${esc(title)}">${icon('arrow')}</button></div>`;}
  function brandingPage() {
    const d=brandDraft;
    return heading('À votre image.',`Offrez à vos collaborateurs un espace aux couleurs de ${esc(activeOrg().name)}.`)+`<div class="brand-columns"><form id="branding-form" class="card"><div class="card-header"><div><h2>L’identité de votre espace</h2><p>Les changements seront visibles dans l’application après enregistrement.</p></div></div><div class="card-pad"><div class="field"><label>Logo de l’entreprise</label><div class="logo-upload"><div id="logo-preview" class="logo-preview">${img(d.logo)?`<img src="${img(d.logo)}" alt="Logo actuel">`:esc(initial(d.shortName||d.name))}</div><div class="logo-controls"><div class="row"><button class="button small" type="button" data-action="import-logo">${icon('upload')} Importer un logo</button><input class="file-input" id="logo-file" type="file" hidden accept="image/png,image/jpeg,image/webp"><button class="button small subtle" type="button" data-action="remove-logo">Retirer</button></div><span class="hint">PNG, JPG ou WebP · 8 Mo maximum</span></div></div></div><div class="divider"></div><div class="field-grid"><div class="field"><label for="brand-name">Nom de l’entreprise</label><input id="brand-name" name="name" data-brand="name" value="${esc(d.name)}" required maxlength="60"></div><div class="field"><label for="brand-short">Nom court</label><input id="brand-short" name="shortName" data-brand="shortName" value="${esc(d.shortName||'')}" required maxlength="24"></div></div><div class="field"><label for="brand-program">Nom du programme</label><input id="brand-program" name="program" data-brand="program" value="${esc(d.program||'')}" required maxlength="60"><span class="hint">Par exemple : Ensemble en mouvement, Élan solidaire…</span></div><div class="divider"></div><div class="field-grid">${colorField('color','Couleur principale',d.color)}${colorField('accent','Couleur secondaire',d.accent)}</div><div class="callout">${icon('info')}<div><strong>Un seul Moov’On, votre propre univers</strong>Votre identité s’applique après connexion. Le nom de l’application reste Moov’On.</div></div></div><div class="save-bar"><span class="save-status" id="brand-save-status">Tous les changements sont enregistrés.</span><button class="button primary" type="submit">${icon('check')} Enregistrer</button></div></form><aside class="preview-card"><div class="preview-title">Aperçu salarié <span>Mise à jour en direct</span></div><div class="phone-preview" id="phone-preview">${phonePreview(d)}</div><p class="preview-caption">Un aperçu de votre identité visuelle.<br>Retrouvez le parcours complet dans l’application.</p></aside></div>`;
  }
  function colorField(key,label,value) {return `<div class="field"><label for="${key}-hex">${label}</label><div class="color-input-row"><input type="color" id="${key}-picker" data-color="${key}" value="${hex(value)}" aria-label="Choisir ${label.toLowerCase()}"><input id="${key}-hex" type="text" data-brand="${key}" value="${hex(value)}" pattern="#[0-9a-fA-F]{6}" required maxlength="7" aria-label="Code hexadécimal ${label.toLowerCase()}"></div></div>`;}
  function phonePreview(d) {return `<div class="phone-top"><span>9:41</span><span>● ▰</span></div><div class="phone-header">${mark(d)}<div><strong>${esc(d.name)}</strong><p>${esc(d.program)}</p></div></div><div class="phone-body"><div class="phone-greeting">Bonjour Léa ☀</div><h3>Un petit effort.<br>Un grand impact.</h3><div class="phone-hero"><small>Votre énergie solidaire</small><div class="phone-energy">8 420 ${icon('spark')}</div><p>Chaque mouvement fait la différence.</p></div><div class="phone-section">Les stories de votre collectif</div><div class="preview-stories"><span class="preview-story">＋</span><span class="preview-story">ML</span><span class="preview-story">JD</span><span class="preview-story">AS</span></div><div class="phone-section">Votre campagne solidaire</div><div class="preview-challenge"><strong>Ensemble, allons plus loin.</strong><p>Chaque activité soutient votre mission</p><div class="bar"><span></span></div></div></div><div class="phone-nav"><strong>Accueil</strong><span>Collectif</span><span>Missions</span><span>Profil</span></div>`;}
  function updatePreview() {
    const phone=document.getElementById('phone-preview'); if(!phone)return;
    phone.innerHTML=phonePreview(brandDraft);phone.style.setProperty('--preview-brand',hex(brandDraft.color));phone.style.setProperty('--preview-accent',hex(brandDraft.accent));phone.style.setProperty('--preview-ink',contrastInk(brandDraft.color));
    document.getElementById('logo-preview').innerHTML=img(brandDraft.logo)?`<img src="${img(brandDraft.logo)}" alt="Logo choisi">`:esc(initial(brandDraft.shortName||brandDraft.name));
    document.getElementById('brand-save-status').textContent='Modifications non enregistrées.';
  }
  function peoplePage() {
    const people=members(), pending=Demo.invitations(activeOrg().id).filter(x=>x.status==='pending'&&x.expiresAt>Demo.now());
    return heading('Le collectif commence ici.','Invitez vos collaborateurs et gérez les accès à votre espace.',`<button class="button primary" data-action="invite">${icon('plus')} Inviter un collaborateur</button>`)+`<section class="card"><div class="toolbar"><label class="search-box">${icon('search')}<span class="sr-only">Rechercher un collaborateur</span><input id="people-search" class="search-input" type="search" placeholder="Rechercher un nom, un e-mail…" value="${esc(peopleSearch)}"></label><select class="select-input" id="people-filter" aria-label="Filtrer par statut">${[['all','Tous les statuts'],['active','Actifs'],['invited','Invités'],['suspended','Suspendus']].map(([v,l])=>`<option value="${v}" ${peopleFilter===v?'selected':''}>${l}</option>`).join('')}</select><span class="pill" style="margin-left:auto">${people.length} collaborateurs</span></div><div id="people-table">${peopleTable()}</div></section><section class="card"><div class="card-header"><div><h2>Invitations en attente</h2><p>Partagez ces liens avec les personnes concernées.</p></div><span class="pill orange">${pending.length}</span></div>${pending.length?`<div class="table-scroll"><table><thead><tr><th>Destinataire</th><th>Expire le</th><th>Lien d’accès</th></tr></thead><tbody>${pending.map(i=>`<tr><td>${esc(i.email)}</td><td>${date(i.expiresAt)}</td><td><button class="button small" data-action="copy-invite" data-token="${esc(i.token)}">${icon('copy')} Copier le lien</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucune invitation en attente. Votre équipe est prête à bouger.</div>'}<div class="wide-note">Les invitations de cette démonstration fonctionnent dans ce navigateur. Aucun e-mail n’est envoyé.</div></section>`;
  }
  function peopleTable() {
    const query=peopleSearch.toLocaleLowerCase('fr'), list=members().filter(u=>(peopleFilter==='all'||u.status===peopleFilter)&&`${u.name} ${u.email} ${u.team}`.toLocaleLowerCase('fr').includes(query));
    return `<div class="table-scroll"><table><thead><tr><th>Collaborateur</th><th>Équipe</th><th>Rôle</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${list.map(u=>`<tr><td><div class="person-cell"><span class="avatar">${esc(initial(u.name))}</span><div><strong>${esc(u.name)}${u.id===current().user.id?' <span class="muted small">(vous)</span>':''}</strong><small>${esc(u.email)}</small></div></div></td><td>${esc(u.team || 'Sans équipe')}</td><td>${roleLabel(u.role)}</td><td>${statusPill(u.status)}</td><td>${u.id===current().user.id||u.role==='platform'?'<span class="muted small">—</span>':u.status==='invited'?'<span class="muted small">Invitation en attente</span>':`<button class="button small ${u.status==='suspended'?'':'subtle'}" data-action="user-status" data-user="${esc(u.id)}" data-status="${u.status==='suspended'?'active':'suspended'}">${u.status==='suspended'?'Réactiver':'Suspendre'}</button>`}</td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">Aucun collaborateur ne correspond à votre recherche.</div>':''}<div class="table-footer">${list.length} collaborateur${list.length>1?'s':''} affiché${list.length>1?'s':''}</div>`;
  }
  function teamsPage() {
    const people=members();
    return heading('Se dépasser, ensemble.','Organisez vos collaborateurs par équipe, service ou établissement.')+`<div class="columns"><form id="teams-form" class="card"><div class="card-header"><div><h2>Les équipes de ${esc(activeOrg().shortName||activeOrg().name)}</h2><p>Des noms courts pour des collectifs faciles à retrouver.</p></div></div><div class="card-pad"><div class="team-list" id="team-list">${teamInputs()}</div><button class="button small" type="button" data-action="add-team" style="margin-top:16px">${icon('plus')} Ajouter une équipe</button></div><div class="save-bar"><span class="save-status">${teamDraft.length} équipes configurées</span><button class="button primary" type="submit">${icon('check')} Enregistrer</button></div></form><section class="card" style="align-self:start"><div class="card-header"><div><h2>Un collectif pour chacun</h2><p>L’organisation actuelle de votre espace</p></div></div><div class="card-pad">${(activeOrg().teams||[]).map(team=>`<div class="row space-between" style="padding:11px 0;border-bottom:1px solid var(--line)"><span style="font-size:12px">${esc(team)}</span><span class="pill">${people.filter(u=>u.team===team).length} membre${people.filter(u=>u.team===team).length>1?'s':''}</span></div>`).join('')}<p class="section-note">Les équipes utilisées par des collaborateurs doivent être conservées pour préserver leur affectation. Les nouvelles équipes seront disponibles lors des prochaines invitations.</p></div></section></div>`;
  }
  function teamInputs() {return teamDraft.map((name,i)=>`<div class="team-edit"><span class="avatar" style="border-radius:8px">${i+1}</span><input name="team" data-team-index="${i}" value="${esc(name)}" placeholder="Nom de l’équipe" maxlength="40" required aria-label="Nom de l’équipe ${i+1}"><button class="icon-button" type="button" data-action="remove-team" data-index="${i}" aria-label="Retirer ${esc(name||'cette équipe')}">${icon('trash')}</button></div>`).join('');}
  function moderationPage() {
    const org=activeOrg(), stories=Demo.getStories(org.id), reports=Demo.reports(org.id).filter(x=>x.status==='open');
    return heading('Une communauté bienveillante.',`Les stories de ${esc(org.name)} sont visibles 24 heures au sein de l’entreprise.`,`<span class="pill green">${stories.length} ${stories.length>1?'stories':'story'} en ligne</span>`)+`<section class="card"><div class="card-header"><div><h2>Signalements à examiner</h2><p>Retirez un contenu inapproprié ou classez le signalement.</p></div><span class="pill ${reports.length?'orange':'green'}">${reports.length}</span></div><div class="${reports.length?'card-pad':'empty'}">${reports.length?reports.map(reportCard).join(''):`${icon('shield')}<p>Aucun signalement ouvert.<br>Votre communauté est à jour.</p>`}</div></section><div class="section-heading"><h2>Stories en ligne</h2><span class="small muted">Expiration automatique après 24 h</span></div><div class="stories-grid">${stories.map(storyCard).join('')}</div>${!stories.length?'<div class="card empty">Aucune story en ligne pour le moment.<br>Publiez-en une depuis l’application pour faire vivre votre collectif.</div>':''}<p class="section-note">Un retrait masque immédiatement la story pour tous les profils de ce navigateur. Seuls les contenus de votre entreprise apparaissent ici.</p>`;
  }
  function storyUser(story) {return members().find(u=>u.id===story.userId)||{name:'Collaborateur',team:''};}
  function remaining(story) {const mins=Math.max(0,Math.ceil((story.expiresAt-Demo.now())/60000));return mins>=60?`${Math.floor(mins/60)} h ${mins%60?`${mins%60} min`:''}`:`${mins} min`;}
  function storyCard(story) {const user=storyUser(story);return `<article class="story-admin"><div class="story-admin-top"><span class="avatar">${esc(initial(user.name))}</span><div><strong>${esc(user.name)}</strong><small>${esc(user.team)}</small></div></div><div class="story-art ${img(story.media)?'has-image':''}" style="background:${hex(story.bg,hex(activeOrg().color))}">${img(story.media)?`<img src="${img(story.media)}" alt="Photo de la story de ${esc(user.name)}">`:''}<div class="story-art-text">${esc(story.text)}</div></div><div class="story-admin-foot"><span class="story-remaining">${icon('clock')} ${remaining(story)}</span><button class="button small danger" data-action="remove-story" data-story="${esc(story.id)}">${icon('trash')} Retirer</button></div></article>`;}
  function reportCard(report) {const story=Demo.getStories(activeOrg().id,{includeExpired:true}).find(s=>s.id===report.storyId);const user=story?storyUser(story):null;return `<div class="report-card"><div class="row space-between"><strong>${user?`Story de ${esc(user.name)}`:'Story indisponible'}</strong><span class="small muted">${date(report.createdAt)}</span></div><p>${esc(report.reason)}</p>${story?`<p style="font-style:italic">« ${esc((story.text||'Story photo').slice(0,180))} »</p>`:''}<div class="report-actions">${story?`<button class="button small" data-action="view-story" data-story="${esc(story.id)}">Voir le contenu</button>`:''}${story&&story.status!=='deleted'&&story.expiresAt>Demo.now()?`<button class="button small danger" data-action="remove-story" data-story="${esc(story.id)}" data-report="${esc(report.id)}">Retirer la story</button>`:''}<button class="button small" data-action="dismiss-report" data-report="${esc(report.id)}">Classer le signalement</button></div></div>`;}
  function presentationPage() {
    const org=activeOrg(), accounts=members().filter(u=>u.status==='active'&&u.role!=='platform').sort((a,b)=>(a.role==='admin'?-1:1)-(b.role==='admin'?-1:1)).slice(0,3);
    return heading('Votre présentation, en toute fluidité.','Retrouvez les parcours à montrer et les outils pour préparer votre démonstration.')+`<div class="columns"><section class="card"><div class="card-header"><div><h2>Un parcours à raconter</h2><p>De l’identité de l’entreprise à l’engagement des salariés.</p></div><span class="pill brand">5 étapes</span></div><div class="card-pad">${[['Une entreprise, son univers','Modifiez le logo et les couleurs, puis retrouvez-les dans l’application.'],['Un accès pour chaque collaborateur','Créez une invitation. Copiez le lien, déconnectez-vous, puis ouvrez-le dans ce même navigateur.'],['Un quotidien qui fait bouger','Ajoutez une activité et transformez l’énergie gagnée en contribution solidaire.'],['Des moments à partager','Publiez une story depuis le rond « Ma story », puis retrouvez-la avec un autre profil de la même entreprise.'],['Une communauté qui reste sereine','Montrez la modération, puis avancez de 24 heures pour vérifier l’expiration des stories.']].map(([t,d],i)=>`<div class="presentation-step"><span class="step-number">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></section><div><section class="card"><div class="card-header"><div><h2>Comptes à utiliser</h2><p>${esc(org.name)} · accès depuis l’écran de connexion</p></div></div>${accounts.map(u=>`<div class="demo-account"><span class="avatar">${esc(initial(u.name))}</span><div><strong>${esc(u.name)} <span class="small muted">· ${u.role==='admin'?'Admin':'Salarié'}</span></strong><p>${esc(u.email)}</p></div><button class="icon-button" data-action="copy" data-value="${esc(u.email)}" aria-label="Copier l’e-mail de ${esc(u.name)}">${icon('copy')}</button></div>`).join('')}<div class="wide-note">Pour changer de profil, déconnectez-vous puis choisissez un compte de démonstration.</div></section><section class="card"><div class="card-header"><div><h2>Accès rapide</h2><p>Deux espaces, une expérience commune.</p></div></div><div class="card-pad"><div class="row wrap"><a class="button primary" href="./index.html">${icon('external')} Ouvrir l’application</a><button class="button" data-action="copy-app-link">${icon('copy')} Copier le lien</button></div></div></section></div></div><div class="section-heading"><h2>Outils de démonstration</h2><span class="pill">Ce navigateur uniquement</span></div><div class="columns"><section class="card card-pad"><div class="row">${icon('clock')}<h3>Tester les 24 heures</h3></div><div class="clock-display">${fullDate(Demo.now())}</div><p class="small muted">Avancez l’horloge de la maquette pour faire expirer les stories, puis vérifiez leur disparition dans l’application.</p><button class="button" data-action="advance-clock" style="margin-top:18px">${icon('clock')} Avancer de 24 heures</button></section><section class="card card-pad" style="margin-top:0"><div class="row">${icon('reset')}<h3>Préparer une nouvelle présentation</h3></div><p class="small muted" style="margin:15px 0 18px">Restaurez les entreprises, comptes, stories et activités de départ. Toutes les modifications locales de la démonstration seront effacées.</p><button class="button danger" data-action="reset">${icon('reset')} Réinitialiser la démonstration</button></section></div><div class="callout" style="margin-top:20px">${icon('info')}<div><strong>Une maquette interactive pour votre présentation</strong>Les comptes, liens d’invitation et contenus sont enregistrés localement. La connexion d’entreprise, l’envoi d’e-mails et la distribution sur les stores seront raccordés pour la production.</div></div>`;
  }
  function enterprisesPage() {
    return heading('Un espace pour chaque entreprise.','Créez vos espaces clients et leur premier compte administrateur.',`<button class="button primary" data-action="create-org">${icon('plus')} Créer une entreprise</button>`)+`<section class="card"><div class="card-header"><div><h2>Vos entreprises clientes</h2><p>Administration réservée à l’équipe Moov’On.</p></div><span class="pill">${Demo.orgs().length} espaces</span></div><div class="table-scroll"><table><thead><tr><th>Entreprise</th><th>Programme</th><th>Collaborateurs</th><th>Équipes</th><th>Actions</th></tr></thead><tbody>${Demo.orgs().map(org=>`<tr><td><div class="person-cell">${mark(org)}<div><strong>${esc(org.name)}</strong><small>${esc(org.domain)}</small></div></div></td><td>${esc(org.program)}</td><td>${Demo.stats(org.id).activeUsers}</td><td>${org.teams.length}</td><td><button class="button small" data-action="manage-org" data-org="${esc(org.id)}">Administrer ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="wide-note">Chaque entreprise dispose de son identité, de ses utilisateurs et de ses contenus. Vous pouvez passer d’un espace à l’autre avec le sélecteur dans le menu.</div></section>`;
  }
  function createOrgModal() {
    showModal('Créer une entreprise',`<p class="small muted" style="margin-bottom:20px">Préparez un nouvel espace et son premier compte administrateur.</p><form id="create-org-form"><div id="create-org-error"></div><div class="field-grid"><div class="field"><label for="org-name">Nom de l’entreprise</label><input id="org-name" name="name" placeholder="Groupe Élan" required maxlength="60"></div><div class="field"><label for="org-short">Nom court</label><input id="org-short" name="shortName" placeholder="Élan" required maxlength="24"></div></div><div class="field"><label for="org-domain">Domaine professionnel</label><input id="org-domain" name="domain" placeholder="elan.fr" required maxlength="150"><span class="hint">Sans https:// ni www. Exemple : elan.fr</span></div><div class="field"><label for="org-program">Nom du programme</label><input id="org-program" name="program" placeholder="Élan en mouvement" required maxlength="60"></div><div class="field-grid"><div class="field"><label for="org-color">Couleur principale</label><input id="org-color" type="color" name="color" value="#1543B7"></div><div class="field"><label for="org-accent">Couleur secondaire</label><input id="org-accent" type="color" name="accent" value="#EFAD42"></div></div><div class="field"><label for="org-teams">Équipes</label><input id="org-teams" name="teams" value="Direction, Équipes" required maxlength="300"><span class="hint">Séparez les équipes par des virgules.</span></div><div class="divider"></div><div class="field"><label for="org-admin-name">Nom de l’administrateur</label><input id="org-admin-name" name="adminName" placeholder="Marie Dupont" required maxlength="70"></div><div class="field"><label for="org-admin-email">E-mail de l’administrateur</label><input id="org-admin-email" type="email" name="adminEmail" placeholder="marie@elan.fr" required maxlength="150"></div><div class="callout">${icon('info')}<div>Le compte administrateur sera immédiatement utilisable dans cette démonstration. Aucun e-mail n’est envoyé.</div></div></form>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button primary" type="submit" form="create-org-form">Créer l’espace ${icon('arrow')}</button>`);
  }
  const euro = cents => (Number(cents || 0)/100).toLocaleString('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:Number(cents||0)%100===0?0:2});
  const decimal = (value,digits=1) => Number(value||0).toLocaleString('fr-FR',{maximumFractionDigits:digits});
  const percent = value => Math.min(100,Math.max(0,Number(value)||0));
  const periodName = value => ({monthly:'Mensuelle',quarterly:'Trimestrielle',yearly:'Annuelle'}[value]||value);
  const dateInput = time => {const d=new Date(time);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  function safeUrl(value) {try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'';}catch{return '';}}
  function campaignStatus(c) {return c.status==='closed'?'Clôturée':c.startAt>Demo.now()?'À venir':c.endAt<=Demo.now()?'Terminée':'En cours';}
  function campaignPill(c) {const status=campaignStatus(c);return `<span class="pill ${status==='En cours'?'green':status==='À venir'?'brand':''}">${status}</span>`;}
  function kpi(label,value,description,highlight=false) {return `<article class="stat ${highlight?'stat-hero':''}"><div class="stat-heading">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${description}</div></article>`;}
  function associationMark(a) {return `<span class="association-mark">${img(a?.logo)?`<img src="${img(a.logo)}" alt="Logo ${esc(a.name)}">`:esc(initial(a?.name||'Association'))}</span>`;}
  function impactOverview() {
    const org=activeOrg(),campaign=Platform.activeCampaign(org.id),s=campaign?Platform.campaignStats(campaign.id):null;
    const community=Demo.stats(org.id),all=Platform.campaigns(org.id);
    const intro=heading('Vue d’ensemble',`${esc(org.name)} · Votre engagement, des résultats concrets.`,`<button class="button primary" data-action="new-campaign">${icon('plus')} Nouvelle campagne</button>`);
    if(!s)return intro+`<section class="hero campaign-empty"><div><div class="eyebrow">Prêt à faire bouger les choses ?</div><h2>Une association. Une mission.<br>Tout un collectif.</h2><p>Choisissez la cause que vous souhaitez soutenir et fixez votre budget. Les activités de vos collaborateurs lui donneront vie.</p></div><button class="button" data-action="new-campaign">Configurer ma campagne ${icon('arrow')}</button></section><div class="stats-grid">${kpi('Campagnes',fmt(all.length),'Votre historique est conservé')}${kpi('Comptes ouverts',fmt(community.activeUsers),'Collaborateurs autorisés à se connecter')}${kpi('Stories en ligne',fmt(community.activeStories),'Des moments partagés pendant 24 h')}${kpi('Signalements',fmt(community.openReports),'À examiner dans la modération')}</div>${all.length?campaignTable(all):''}`;
    return intro+`<section class="campaign-banner"><div class="row">${associationMark(s.association)}<div><div class="eyebrow">${esc(s.association.name)}</div><h2>${esc(campaign.name||s.mission.name)}</h2><p>${date(campaign.startAt)} → ${date(campaign.endAt)} · ${periodName(campaign.period)}</p></div></div><div class="row wrap">${campaignPill(campaign)}<button class="button small" data-page="campaigns">Mes campagnes ${icon('arrow')}</button></div></section>${s.endingSoon?`<div class="renewal-banner">${icon('clock')}<div><strong>La campagne se termine dans ${Math.ceil(s.remainingDays)} jours.</strong><span>Préparez votre prochaine mission pour prolonger l’engagement.</span></div><button class="button small" data-action="new-campaign">Préparer la suite</button></div>`:''}<div class="stats-grid">${kpi('Budget engagé',euro(s.budgetCents),`${periodName(campaign.period)} · financement simulé`,true)}${kpi('Montant mobilisé',euro(s.raisedCents),`${decimal(s.progressPct)} % de votre budget`)}${kpi('Participants actifs',fmt(s.activeParticipants),`Au moins une activité sur les ${Platform.rules().forecast.activeWindowDays} derniers jours`)}${kpi('Temps restant',`${Math.ceil(s.remainingDays)} <small>jours</small>`,`${fmt(s.activityCount)} activités enregistrées`)}</div><div class="impact-columns"><section class="card"><div class="card-header"><div><h2>Progression de votre campagne</h2><p>Contributions cumulées par les activités de votre collectif</p></div><span class="pill brand">${decimal(s.progressPct)} %</span></div><div class="card-pad">${progressChart(s)}<div class="chart-legend"><span><i></i>Montant mobilisé</span><span>Budget : <strong>${euro(s.budgetCents)}</strong></span></div></div></section><section class="card"><div class="card-header"><div><h2>Votre impact prend forme</h2><p>${esc(campaign.unit||s.mission.unit)}</p></div></div><div class="card-pad impact-summary"><div class="impact-orbit" style="--progress:${percent(s.progressPct)}%"><div><strong>${fmt(s.financedImpact)}</strong><span>unités financées</span></div></div><div class="impact-target"><b>${fmt(s.targetImpact)}</b><span>unités possibles avec votre budget</span></div><p>${euro(campaign.unitCostCents)} / ${esc(campaign.unit||s.mission.unit)}</p></div></section></div><div class="impact-columns lower-impact"><section class="card"><div class="card-header"><div><h2>L’énergie du collectif</h2><p>La même activité alimente l’application et votre suivi.</p></div><span class="energy-badge">${icon('spark')}</span></div><div class="card-pad"><div class="energy-total">${fmt(s.totalEnergy)} ${icon('spark')}</div><div class="metric-pairs"><div><strong>${decimal(s.forecast.frequencyPerWeek)}</strong><span>activités / actif / semaine estimées</span></div><div><strong>${fmt(Math.round(s.forecast.averageEnergy))}</strong><span>énergie moyenne estimée par activité</span></div></div><div class="conversion-note">${icon('info')}<p>La conversion est ajustée par Moov’On à votre budget et à l’activité du collectif. Les contributions déjà enregistrées restent acquises.</p></div></div></section><section class="card"><div class="card-header"><div><h2>Votre budget, en clair</h2><p>Le montant mobilisé reste plafonné au budget engagé.</p></div></div><div class="card-pad"><div class="budget-summary"><div><span>Mobilisé</span><strong>${euro(s.raisedCents)}</strong></div><div><span>Disponible</span><strong>${euro(s.remainingCents)}</strong></div></div><div class="budget-track" role="progressbar" aria-label="Budget mobilisé" aria-valuenow="${percent(s.progressPct)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent(s.progressPct)}%"></span></div><p class="section-note">${fmt(s.energyRequired)} points d’énergie estimés pour mobiliser le budget restant, au taux actuellement calculé.</p><div class="simulation-caption">Démonstration de financement · aucun paiement effectué.</div></div></section></div>`;
  }
  function progressChart(s) {
    const c=s.campaign,activities=Platform.activities(c.orgId).filter(a=>a.campaignId===c.id&&a.at<=Demo.now()).sort((a,b)=>a.at-b.at);
    const left=14,right=586,top=15,bottom=157,until=Math.max(c.startAt+1,Math.min(Demo.now(),c.endAt)),range=until-c.startAt;
    const max=Math.max(100,s.budgetCents),points=[[left,bottom]];let total=0;
    activities.forEach(a=>{total+=Number(a.contributionCents)||0;points.push([left+Math.max(0,Math.min(1,(a.at-c.startAt)/range))*(right-left),bottom-Math.min(1,total/max)*(bottom-top)]);});
    points.push([right,bottom-Math.min(1,total/max)*(bottom-top)]);
    const line=points.map(([x,y])=>`${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
    return `<div class="progress-chart" role="img" aria-label="Progression : ${esc(euro(s.raisedCents))} mobilisés sur ${esc(euro(s.budgetCents))}"><div class="chart-value">${euro(s.raisedCents)}<span>mobilisés à ce jour</span></div><svg viewBox="0 0 600 180" aria-hidden="true"><line x1="14" y1="15" x2="586" y2="15" stroke="#D7DFEC" stroke-dasharray="4 5"/><line x1="14" y1="86" x2="586" y2="86" stroke="#E8EDF4"/><line x1="14" y1="157" x2="586" y2="157" stroke="#E8EDF4"/><polygon points="${line} ${right},${bottom} ${left},${bottom}" fill="var(--brand)" opacity=".07" stroke="none"/><polyline points="${line}" fill="none" stroke="var(--brand)" stroke-width="3.5" stroke-linejoin="round"/><circle cx="${right}" cy="${points.at(-1)[1]}" r="4" fill="var(--brand)" stroke="white" stroke-width="2"/></svg><div class="chart-dates"><span>${date(c.startAt)}</span><span>${date(until)}</span></div></div>`;
  }
  function campaignsPage() {
    const list=Platform.campaigns(activeOrg().id);
    return heading('Campagnes solidaires','Une association, une mission, un budget. Votre engagement commence ici.',`<button class="button primary" data-action="new-campaign">${icon('plus')} Nouvelle campagne</button>`)+`<div class="campaign-steps"><div><span>01</span><strong>Choisir une association</strong></div><i>→</i><div><span>02</span><strong>Sélectionner sa mission</strong></div><i>→</i><div><span>03</span><strong>Fixer budget et période</strong></div></div>${list.length?campaignTable(list):'<section class="card empty">Aucune campagne configurée. Choisissez votre première mission solidaire.</section>'}<div class="callout" style="margin-top:22px">${icon('info')}<div><strong>Votre budget finance une mission concrète.</strong>Les associations et leurs missions sont préparées par Moov’On. Vous choisissez votre engagement ; la conversion de l’énergie est calculée par la plateforme.</div></div>`;
  }
  function campaignTable(list) {
    return `<section class="card"><div class="card-header"><div><h2>Vos campagnes</h2><p>Campagnes en cours, programmées et terminées</p></div><span class="pill">${list.length}</span></div><div class="table-scroll"><table><thead><tr><th>Association & mission</th><th>Période</th><th>Budget</th><th>Progression</th><th>Statut</th><th></th></tr></thead><tbody>${list.map(c=>{const s=Platform.campaignStats(c.id);return `<tr><td><div class="person-cell">${associationMark(s.association)}<div><strong>${esc(c.name||s.mission.name)}</strong><small>${esc(s.association.name)}</small></div></div></td><td><strong>${periodName(c.period)}</strong><div class="small muted" style="margin-top:5px">${date(c.startAt)} → ${date(c.endAt)}</div></td><td class="table-amount">${euro(c.budgetCents)}</td><td><div class="table-progress"><span>${euro(s.raisedCents)}</span><b>${decimal(s.progressPct)} %</b><div class="bar"><span style="width:${percent(s.progressPct)}%"></span></div></div></td><td>${campaignPill(c)}</td><td><button class="button small" data-action="campaign-detail" data-id="${esc(c.id)}">Voir ${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div></section>`;
  }
  function newCampaignModal() {
    const associations=Platform.catalog().associations;
    campaignDraft={associationId:'',missionId:'',budgetEuros:10000,period:'yearly',startDate:dateInput(Demo.now())};
    showModal('Nouvelle campagne solidaire',`<form id="campaign-form"><div id="campaign-error"></div><div class="form-section-label"><span>01</span> Votre cause</div><div class="field"><label for="campaign-association">Association</label><select id="campaign-association" name="associationId" required><option value="">Choisir une association</option>${associations.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="campaign-mission">Mission à soutenir</label><select id="campaign-mission" name="missionId" required disabled><option value="">Choisissez d’abord une association</option></select></div><div id="campaign-mission-preview"></div><div class="divider"></div><div class="form-section-label"><span>02</span> Votre engagement</div><div class="field"><label for="campaign-budget">Budget consacré à cette campagne (€)</label><input id="campaign-budget" name="budgetEuros" type="number" min="0.01" max="100000000" step="0.01" value="10000" required inputmode="decimal"><span class="hint">Financement simulé pour la présentation. Aucun paiement.</span></div><div class="field-grid"><div class="field"><label for="campaign-period">Période</label><select id="campaign-period" name="period"><option value="monthly">Mensuelle · 1 mois</option><option value="quarterly">Trimestrielle · 3 mois</option><option value="yearly" selected>Annuelle · 12 mois</option></select></div><div class="field"><label for="campaign-start">Début de la campagne</label><input id="campaign-start" name="startDate" type="date" value="${campaignDraft.startDate}" required></div></div><div id="campaign-summary" aria-live="polite"></div><div id="campaign-conflict"></div><div class="callout">${icon('spark')}<div>Moov’On ajuste la conversion de l’énergie à votre budget et à l’activité de vos équipes.</div></div></form>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button primary" form="campaign-form" type="submit">Créer la campagne ${icon('arrow')}</button>`,'drawer-modal');
    refreshCampaignPreview();
  }
  function refreshCampaignPreview() {
    const form=document.getElementById('campaign-form');if(!form)return;
    const d=Object.fromEntries(new FormData(form));campaignDraft={...campaignDraft,...d};
    const catalog=Platform.catalog(),mission=catalog.missions.find(m=>m.id===d.missionId);
    document.getElementById('campaign-mission-preview').innerHTML=mission?`<div class="mission-selection"><span class="eyebrow">${esc(catalog.associations.find(a=>a.id===mission.associationId)?.name)}</span><h3>${esc(mission.name)}</h3><p>${esc(mission.description)}</p><div><span>${euro(mission.unitCostCents)} / ${esc(mission.unit)}</span><span>Objectif de la mission : <b>${euro(mission.goalCents)}</b></span></div></div>`:'';
    let endAt,startAt;try{startAt=new Date(`${d.startDate}T00:00:00Z`).getTime();endAt=Energy.campaignEnd(startAt,d.period);}catch{}
    const cents=Math.round(Number(d.budgetEuros)*100),impact=mission&&Number.isFinite(cents)?Math.floor(cents/mission.unitCostCents):0;
    document.getElementById('campaign-summary').innerHTML=Number.isFinite(endAt)?`<div class="campaign-summary"><div><span>Fin de campagne</span><strong>${date(endAt)}</strong></div><div><span>Impact possible</span><strong>${mission?`${fmt(impact)} <small>${esc(mission.unit)}</small>`:'Choisissez une mission'}</strong></div></div>`:'';
    const conflicts=Number.isFinite(endAt)?Platform.campaigns(activeOrg().id).filter(c=>c.status!=='closed'&&c.startAt<endAt&&startAt<c.endAt):[];
    const previous=document.getElementById('replace-campaign')?.checked;
    document.getElementById('campaign-conflict').innerHTML=conflicts.length?`<label class="replacement-check"><input type="checkbox" name="replaceActive" id="replace-campaign" ${previous?'checked':''} required><span><strong>Confirmer la succession des campagnes</strong>Une campagne couvre déjà cette période. La nouvelle prendra le relais à sa date de début. Les budgets et contributions précédents resteront dans l’historique.</span></label>`:'';
  }
  function campaignDetail(id) {
    const s=Platform.campaignStats(id),c=s.campaign;
    showModal(esc(c.name||s.mission.name),`<div class="row" style="margin-bottom:22px">${associationMark(s.association)}<div><h3>${esc(s.association.name)}</h3><p class="small muted">${date(c.startAt)} → ${date(c.endAt)} · ${periodName(c.period)}</p></div>${campaignPill(c)}</div><div class="campaign-detail-stats"><div><span>Budget engagé</span><strong>${euro(s.budgetCents)}</strong></div><div><span>Montant mobilisé</span><strong>${euro(s.raisedCents)}</strong></div><div><span>Impact financé</span><strong>${fmt(s.financedImpact)} <small>${esc(c.unit||s.mission.unit)}</small></strong></div><div><span>Participants actifs</span><strong>${s.activeParticipants}</strong></div></div>${progressChart(s)}<p class="section-note">${fmt(s.totalEnergy)} points d’énergie issus de ${fmt(s.activityCount)} activités. Les montants correspondent aux contributions enregistrées pour cette campagne.</p>`,`<button class="button" data-action="close-modal">Fermer</button>`,'drawer-modal');
  }
  function associationsPage() {
    const catalog=Platform.catalog(),associations=catalog.associations.filter(a=>!catalogueFilter||a.id===catalogueFilter);
    return heading('Associations & missions','Le catalogue solidaire proposé aux entreprises. Les objectifs sont exprimés en euros.',`<button class="button primary" data-action="edit-association">${icon('plus')} Nouvelle association</button>`)+`<div class="catalogue-toolbar"><label for="catalogue-filter">Afficher une association</label><select class="select-input" id="catalogue-filter"><option value="">Toutes les associations</option>${catalog.associations.map(a=>`<option value="${esc(a.id)}" ${a.id===catalogueFilter?'selected':''}>${esc(a.name)}</option>`).join('')}</select><span class="pill brand">CRM Moov’On</span></div><div class="association-list">${associations.map(a=>associationCard(a,catalog.missions.filter(m=>m.associationId===a.id))).join('')||'<section class="card empty">Ajoutez votre première association pour construire le catalogue.</section>'}</div>`;
  }
  function associationCard(a,missions) {
    return `<section class="card association-card"><div class="association-head"><div class="row">${associationMark(a)}<div><h2>${esc(a.name)}</h2><p>${esc(a.description||'Aucune description renseignée.')}</p><div class="association-contact">${safeUrl(a.website)?`<a href="${esc(safeUrl(a.website))}" target="_blank" rel="noopener noreferrer">${icon('external')} Site de l’association</a>`:''}${a.contact?`<span>${icon('mail')} ${esc(a.contact)}</span>`:''}</div></div></div><button class="button small" data-action="edit-association" data-id="${esc(a.id)}">Modifier</button></div><div class="mission-list-heading"><h3>${missions.length} mission${missions.length>1?'s':''}</h3><button class="button small" data-action="edit-mission" data-association="${esc(a.id)}">${icon('plus')} Ajouter une mission</button></div>${missions.length?`<div class="table-scroll"><table><thead><tr><th>Mission & impact</th><th>Coût unitaire</th><th>Objectif €</th><th>Mobilisé</th><th></th></tr></thead><tbody>${missions.map(m=>{const s=Platform.missionStats(m.id);return `<tr><td><strong>${esc(m.name)}</strong><div class="small muted" style="margin-top:5px">${esc(m.unit)}</div></td><td class="table-amount">${euro(m.unitCostCents)}</td><td class="table-amount">${euro(m.goalCents)}</td><td><div class="table-progress"><span>${euro(s.raisedCents)}</span><div class="bar"><span style="width:${percent(s.raisedCents/Math.max(1,s.goalCents)*100)}%"></span></div></div></td><td><button class="button small subtle" data-action="edit-mission" data-id="${esc(m.id)}">Modifier</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">Ajoutez une mission pour que les entreprises puissent soutenir cette association.</div>'}</section>`;
  }
  function associationModal(id) {
    const a=id?Platform.catalog().associations.find(a=>a.id===id):null;
    if(id&&!a)throw new Error('Cette association est introuvable.');
    associationDraft={id:a?.id,name:a?.name||'',description:a?.description||'',website:a?.website||'',contact:a?.contact||'',logo:a?.logo||''};
    showModal(a?'Modifier l’association':'Nouvelle association',`<form id="association-form"><div id="association-error"></div><div class="field"><label>Logo de l’association</label><div class="logo-upload"><div class="logo-preview" id="association-logo-preview">${img(associationDraft.logo)?`<img src="${img(associationDraft.logo)}" alt="Logo de l’association">`:icon('shield')}</div><div class="logo-controls"><button class="button small" type="button" data-action="import-association-logo">${icon('upload')} Importer un logo</button><button class="button small subtle" type="button" data-action="remove-association-logo">Retirer le logo</button><span class="hint">PNG, JPG ou WebP · 8 Mo maximum</span></div><input type="file" id="association-logo-file" hidden accept="image/png,image/jpeg,image/webp"></div></div><div class="field"><label for="association-name">Nom de l’association</label><input id="association-name" name="name" value="${esc(associationDraft.name)}" maxlength="100" required></div><div class="field"><label for="association-description">Présentation</label><textarea id="association-description" name="description" rows="4" maxlength="1500">${esc(associationDraft.description)}</textarea></div><div class="field"><label for="association-website">Site internet</label><input id="association-website" name="website" type="url" value="${esc(associationDraft.website)}" placeholder="https://association.fr" maxlength="500"></div><div class="field"><label for="association-contact">Contact</label><input id="association-contact" name="contact" value="${esc(associationDraft.contact)}" placeholder="Nom, e-mail ou téléphone du contact" maxlength="400"></div></form>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button primary" type="submit" form="association-form">${icon('check')} Enregistrer l’association</button>`,'drawer-modal');
  }
  function missionModal(id,associationId) {
    const catalog=Platform.catalog(),m=id?catalog.missions.find(m=>m.id===id):null;
    if(id&&!m)throw new Error('Cette mission est introuvable.');
    const association=m?.associationId||associationId||'';
    showModal(m?'Modifier la mission':'Nouvelle mission',`<form id="mission-form" data-id="${esc(m?.id||'')}"><div id="mission-error"></div><div class="field"><label for="mission-association">Association</label><select id="mission-association" name="associationId" required><option value="">Choisir une association</option>${catalog.associations.map(a=>`<option value="${esc(a.id)}" ${a.id===association?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="mission-name">Nom de la mission</label><input id="mission-name" name="name" value="${esc(m?.name||'')}" placeholder="Planter une forêt urbaine" required maxlength="120"></div><div class="field"><label for="mission-description">Description de la mission</label><textarea id="mission-description" name="description" rows="3" maxlength="1500">${esc(m?.description||'')}</textarea></div><div class="field"><label for="mission-unit">Unité d’impact</label><input id="mission-unit" name="unit" value="${esc(m?.unit||'')}" placeholder="arbre planté, repas servi, kit distribué…" required maxlength="60"></div><div class="field-grid"><div class="field"><label for="mission-cost">Coût d’une unité (€)</label><input id="mission-cost" name="unitCostEuros" type="number" value="${m?m.unitCostCents/100:25}" required min="0.01" max="100000000" step="0.01" inputmode="decimal"></div><div class="field"><label for="mission-goal">Objectif de la mission (€)</label><input id="mission-goal" name="goalEuros" type="number" value="${m?m.goalCents/100:10000}" required min="0.01" max="100000000" step="0.01" inputmode="decimal"></div></div><div class="callout">${icon('info')}<div>Les entreprises sélectionnent cette mission et définissent leur propre budget. Les campagnes déjà créées conservent leur coût unitaire et leurs contributions.</div></div></form>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button primary" type="submit" form="mission-form">${icon('check')} Enregistrer la mission</button>`,'drawer-modal');
  }
  async function readAssociationLogo(file) {
    if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choisissez un fichier PNG, JPG ou WebP.');if(file.size>8*1024*1024)throw new Error('Le logo doit peser moins de 8 Mo.');
    const url=URL.createObjectURL(file);try{const picture=new Image();await new Promise((resolve,reject)=>{picture.onload=resolve;picture.onerror=()=>reject(new Error('Ce fichier image est illisible.'));picture.src=url;});if(picture.width*picture.height>40000000)throw new Error('Choisissez une image de moins de 40 millions de pixels.');const factor=Math.min(1,512/picture.width,512/picture.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(picture.width*factor));canvas.height=Math.max(1,Math.round(picture.height*factor));canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);associationDraft.logo=canvas.toDataURL('image/webp',.85);document.getElementById('association-logo-preview').innerHTML=`<img src="${associationDraft.logo}" alt="Logo sélectionné">`;notify('Logo prêt. Enregistrez l’association pour le publier.');}finally{URL.revokeObjectURL(url);}
  }
  function rulesPage() {
    const rules=Platform.rules(),sports=Object.keys(rules.sports);
    return heading('Conversion & énergie','Les paramètres Moov’On, appliqués à toutes les nouvelles activités.',`<span class="pill brand">Barème · version ${rules.version}</span>`)+`<div class="callout rules-intro">${icon('spark')}<div><strong>Une énergie commune, un budget propre à chaque entreprise</strong>La distance, le sport et la vitesse produisent de l’énergie. La conversion en euros dépend ensuite du budget restant, de la durée et des participants réellement actifs. Ces paramètres de présentation ne sont pas une équivalence physiologique.</div></div><form id="rules-form"><div id="rules-error"></div><section class="card"><div class="card-header"><div><h2>01 · Barème par activité</h2><p>Des mètres parcourus à l’énergie gagnée</p></div><span class="energy-badge">${icon('spark')}</span></div><div class="table-scroll"><table class="rules-table"><thead><tr><th>Sport</th><th>Énergie par mètre</th><th>Vitesse de référence (km/h)</th></tr></thead><tbody>${sports.map((sport,i)=>`<tr><td><strong>${esc(sport)}</strong></td><td><label class="sr-only" for="sport-points-${i}">Énergie par mètre · ${esc(sport)}</label><input class="rules-number" id="sport-points-${i}" name="sport-points-${i}" type="number" min="0.001" step="any" required value="${rules.sports[sport].pointsPerMeter}"></td><td><label class="sr-only" for="sport-speed-${i}">Vitesse de référence · ${esc(sport)}</label><input class="rules-number" id="sport-speed-${i}" name="sport-speed-${i}" type="number" min="0.1" step="any" required value="${rules.sports[sport].referenceSpeedKmh}"></td></tr>`).join('')}</tbody></table></div><div class="wide-note">Énergie de base = distance en mètres × coefficient du sport. Un bonus limité peut s’ajouter selon le rapport entre la vitesse de l’activité et sa référence.</div></section><section class="card"><div class="card-header"><div><h2>02 · Bonus d’intensité</h2><p>Des seuils progressifs et un bonus plafonné à 10 %</p></div></div><div class="card-pad"><div class="rules-tiers">${rules.bonusTiers.map((tier,i)=>`<div class="rule-tier"><div class="field"><label ${tier.maxRatio===null?'':`for="tier-ratio-${i}"`}>${tier.maxRatio===null?'Au-delà du dernier seuil':'Rapport de vitesse maximal'}</label>${tier.maxRatio===null?'<div class="rules-infinity">∞ <span>Dernier palier</span></div>':`<input id="tier-ratio-${i}" name="tier-ratio-${i}" type="number" min="0.001" step="any" required value="${tier.maxRatio}">`}</div><div class="field"><label for="tier-bonus-${i}">Bonus (%) · palier ${i+1}</label><input id="tier-bonus-${i}" name="tier-bonus-${i}" type="number" min="0" max="10" step="any" required value="${tier.bonusPct}"></div></div>`).join('')}</div><div class="field rules-limit"><label for="rule-maxBonusPct">Plafond du bonus (%)</label><input id="rule-maxBonusPct" name="maxBonusPct" type="number" min="0" max="10" step="any" required value="${rules.maxBonusPct}"><span class="hint">Un bonus calculé plus élevé sera ramené à ce plafond.</span></div></div></section><section class="card"><div class="card-header"><div><h2>03 · Conversion énergie → euros</h2><p>La prévision adapte chaque campagne à son collectif.</p></div></div><div class="card-pad"><div class="forecast-fields">${forecastField('maxEuroPerEnergy','Plafond de conversion (€ / énergie)',rules.forecast.maxEuroPerEnergy,'Limite haute appliquée au taux calculé par campagne.',.000001,'any')}${forecastField('activeWindowDays','Fenêtre des participants actifs (jours)',rules.forecast.activeWindowDays,'Une activité au moins dans cette fenêtre pour être compté actif.',1,1,366)}${forecastField('defaultActivitiesPerWeek','Fréquence initiale (activités / semaine)',rules.forecast.defaultActivitiesPerWeek,'Hypothèse par participant avant une observation suffisante.',.01,'any')}${forecastField('defaultEnergy','Énergie initiale par activité',rules.forecast.defaultEnergy,'Hypothèse utilisée au démarrage de la campagne.',1,'any')}${forecastField('minObservationDays','Observation minimale (jours)',rules.forecast.minObservationDays,'Stabilise la prévision au début de la campagne.',.01,'any')}${forecastField('priorWeeks','Poids de la fréquence initiale (semaines)',rules.forecast.priorWeeks,'Lisse la transition vers la fréquence réellement observée.',0,'any')}${forecastField('priorActivities','Poids de l’énergie initiale (activités)',rules.forecast.priorActivities,'Lisse la transition vers l’énergie réellement observée.',0,'any')}</div><div class="conversion-note">${icon('info')}<p>Le nombre de comptes inscrits ne détermine pas la conversion. La prévision prend en compte les participants actifs, leurs activités et l’énergie produite. Aucune contribution ne dépasse le budget restant.</p></div></div><div class="save-bar"><span class="save-status">Les activités déjà enregistrées conservent leur valeur.</span><button class="button primary" type="submit">${icon('check')} Enregistrer les règles</button></div></section></form>${conversionSimulation(rules)}`;
  }
  function forecastField(key,label,value,hint,min=0,step='any',max='') {return `<div class="field"><label for="forecast-${key}">${label}</label><input id="forecast-${key}" name="forecast-${key}" type="number" required min="${min}" step="${step}" ${max!==''?`max="${max}"`:''} value="${value}"><span class="hint">${hint}</span></div>`;}
  function conversionSimulation(rules) {
    const rows=[20,200].map(activeParticipants=>{const activityCount=activeParticipants*8,totalEnergy=activityCount*5000;return {activeParticipants,forecast:Energy.forecast({budgetCents:1000000,raisedCents:0,activeParticipants,activityCount,totalEnergy,observationDays:28,remainingDays:90},rules)};});
    return `<section class="card simulation-card"><div class="card-header"><div><h2>Comprendre avec 20 ou 200 participants</h2><p>Simulation indépendante · budget identique de 10 000 € · 90 jours restants</p></div><span class="pill">Illustration</span></div><div class="table-scroll"><table><thead><tr><th>Collectif actif</th><th>Énergie prévue</th><th>Taux calculé (€ / énergie)</th><th>Budget simulé</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${row.activeParticipants} participants</strong></td><td>${fmt(Math.round(row.forecast.expectedEnergy))}</td><td>${decimal(row.forecast.ratioEuroPerEnergy,6)} €</td><td>10 000 €</td></tr>`).join('')}</tbody></table></div><div class="wide-note">Hypothèses communes : 8 activités par participant sur les 28 derniers jours, 5 000 points par activité. Le taux est recalculé avec les règles enregistrées ci-dessus. Ce scénario n’ajoute aucune activité ni contribution aux entreprises.</div></section>`;
  }
  function showModal(title,body,footer='',extraClass='') {
    lastFocus=document.activeElement; modalRoot.innerHTML=`<div class="overlay ${extraClass?'drawer-overlay':''}" data-overlay="true"><section class="modal ${extraClass}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';
    requestAnimationFrame(()=>{(modalRoot.querySelector('input:not([type="file"]):not([type="hidden"]),select:not(:disabled),textarea')||modalRoot.querySelector('button'))?.focus();});
  }
  function closeModal() {modalRoot.innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();lastFocus=null;}
  function inviteModal() {const org=activeOrg();showModal('Inviter un collaborateur',`<p class="small muted" style="margin-bottom:21px">Créez un accès personnel à ${esc(org.name)}, puis partagez le lien d’invitation.</p><form id="invite-form"><div id="invite-error"></div><div class="field"><label for="invite-name">Prénom et nom</label><input id="invite-name" name="name" autocomplete="name" placeholder="Camille Martin" required maxlength="70"></div><div class="field"><label for="invite-email">E-mail professionnel</label><input id="invite-email" name="email" type="email" autocomplete="email" placeholder="camille@${esc(org.domain||'entreprise.fr')}" required maxlength="150"></div><div class="field-grid"><div class="field"><label for="invite-team">Équipe</label><select id="invite-team" name="team" required><option value="">Choisir une équipe</option>${(org.teams||[]).map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="invite-role">Rôle</label><select id="invite-role" name="role"><option value="employee">Collaborateur</option><option value="admin">Administrateur</option></select></div></div><div class="callout">${icon('mail')}<div>Un lien sera créé dans ce navigateur. Aucun e-mail n’est envoyé pendant la démonstration.</div></div></form>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button primary" type="submit" form="invite-form">Créer l’invitation ${icon('arrow')}</button>`);}
  function inviteUrl(token) {const url=new URL('./index.html',location.href);url.search='';url.hash='';url.searchParams.set('invite',token);return url.href;}
  async function copy(value) {
    try {await navigator.clipboard.writeText(String(value));}
    catch {const field=document.createElement('textarea');field.value=String(value);field.style.cssText='position:fixed;left:-9999px';document.body.appendChild(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw new Error('La copie est indisponible. Sélectionnez le lien pour le copier.');}
    notify('Copié dans le presse-papiers.');
  }
  async function importLogo(file) {
    if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choisissez un fichier PNG, JPG ou WebP.');if(file.size>8*1024*1024)throw new Error('Le logo doit peser moins de 8 Mo.');
    const source=URL.createObjectURL(file);
    try {const picture=new Image();await new Promise((resolve,reject)=>{picture.onload=resolve;picture.onerror=()=>reject(new Error('Ce fichier image est illisible.'));picture.src=source;});if(!picture.width||!picture.height||picture.width*picture.height>40000000)throw new Error('Cette image est trop grande. Choisissez un logo plus petit.');const ratio=Math.min(1,512/picture.width,512/picture.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(picture.width*ratio));canvas.height=Math.max(1,Math.round(picture.height*ratio));canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);brandDraft.logo=canvas.toDataURL('image/webp',.85);updatePreview();notify('Logo ajouté à l’aperçu. Enregistrez pour le publier.');}
    finally {URL.revokeObjectURL(source);}
  }
  function confirmModal(title,message,action,attributes='',label='Confirmer',danger=false) {showModal(title,`<p class="muted" style="font-size:13px">${message}</p>`,`<button class="button" data-action="close-modal">Annuler</button><button class="button ${danger?'danger':'primary'}" data-action="${action}" ${attributes}>${label}</button>`);}
  function goPage(target) {if(!Object.hasOwn(titles,target))return;page=target;history.replaceState(null,'',`#${target}`);render();window.scrollTo({top:0,behavior:'instant'});}
  document.addEventListener('click',async e=>{
    const navButton=e.target.closest('[data-page]');if(navButton){goPage(navButton.dataset.page);return;}
    const trigger=e.target.closest('[data-action]');if(!trigger){if(e.target.dataset.overlay)closeModal();return;}
    const action=trigger.dataset.action;
    try {
      if(action==='close-modal'){closeModal();return;}
      if(action==='menu'){const sidebar=document.getElementById('sidebar');const open=sidebar.classList.toggle('mobile-open');trigger.setAttribute('aria-expanded',String(open));return;}
      if(!current()||!Demo.canAdmin()){render();return;}
      if(action==='logout'){Demo.logout();location.href='./index.html';}
      if(action==='invite')inviteModal();
      if(action==='new-campaign')newCampaignModal();
      if(action==='campaign-detail')campaignDetail(trigger.dataset.id);
      if(action==='edit-association'&&current().user.role==='platform')associationModal(trigger.dataset.id);
      if(action==='edit-mission'&&current().user.role==='platform')missionModal(trigger.dataset.id,trigger.dataset.association);
      if(action==='import-association-logo'){document.getElementById('association-logo-file').click();return;}
      if(action==='remove-association-logo'){associationDraft.logo='';document.getElementById('association-logo-preview').innerHTML=icon('shield');}
      if(action==='create-org'&&current().user.role==='platform')createOrgModal();
      if(action==='manage-org'&&current().user.role==='platform'){selectOrg(trigger.dataset.org);goPage('overview');}
      if(action==='copy')await copy(trigger.dataset.value);
      if(action==='copy-invite')await copy(inviteUrl(trigger.dataset.token));
      if(action==='copy-app-link')await copy(new URL('./index.html',location.href).href);
      if(action==='import-logo'){document.getElementById('logo-file').click();return;}
      if(action==='remove-logo'){brandDraft.logo='';updatePreview();}
      if(action==='add-team'){if(teamDraft.length>=30)throw new Error('La maquette accepte jusqu’à 30 équipes.');teamDraft.push('');document.getElementById('team-list').innerHTML=teamInputs();document.querySelector('[data-team-index="'+(teamDraft.length-1)+'"]')?.focus();}
      if(action==='remove-team'){const index=Number(trigger.dataset.index);if(members().some(u=>u.team===teamDraft[index]))throw new Error('Cette équipe contient des collaborateurs. Conservez-la pour garder leur affectation.');teamDraft.splice(index,1);document.getElementById('team-list').innerHTML=teamInputs();}
      if(action==='user-status'){const user=members().find(u=>u.id===trigger.dataset.user);if(!user)throw new Error('Ce collaborateur est introuvable.');if(trigger.dataset.status==='active'){mutate(()=>Demo.setUserStatus(user.id,'active'));render();notify('Accès réactivé.');}else confirmModal('Suspendre cet accès ?',`${esc(user.name)} ne pourra plus accéder à l’espace entreprise. Vous pourrez réactiver son compte à tout moment.`,'confirm-suspend',`data-user="${esc(user.id)}"`,'Suspendre',true);}
      if(action==='confirm-suspend'){mutate(()=>Demo.setUserStatus(trigger.dataset.user,'suspended'));closeModal();render();notify('Accès suspendu.');}
      if(action==='remove-story'){confirmModal('Retirer cette story ?',`Cette story disparaîtra de l’espace ${esc(activeOrg().name)}. Son auteur et les collaborateurs ne pourront plus la consulter.`,'confirm-remove-story',`data-story="${esc(trigger.dataset.story)}" ${trigger.dataset.report?`data-report="${esc(trigger.dataset.report)}"`:''}`,'Retirer la story',true);}
      if(action==='confirm-remove-story'){mutate(()=>Demo.deleteStory(trigger.dataset.story));closeModal();render();notify('Story retirée de la communauté.');}
      if(action==='dismiss-report'){mutate(()=>Demo.dismissReport(trigger.dataset.report));render();notify('Signalement classé.');}
      if(action==='view-story'){const story=Demo.getStories(activeOrg().id,{includeExpired:true}).find(s=>s.id===trigger.dataset.story);if(!story)throw new Error('Cette story n’est plus disponible.');showModal(`Story de ${esc(storyUser(story).name)}`,`<div class="story-art ${img(story.media)?'has-image':''}" style="height:420px;border-radius:12px;background:${hex(story.bg)}">${img(story.media)?`<img src="${img(story.media)}" alt="Photo de la story">`:''}<div class="story-art-text">${esc(story.text)}</div></div><p class="small muted" style="margin-top:12px">Publiée le ${fullDate(story.publishedAt)} · ${story.expiresAt>Demo.now()?'Expire dans '+remaining(story):'Expirée'}</p>`);}
      if(action==='advance-clock')confirmModal('Avancer de 24 heures ?','L’horloge de la démonstration avancera d’un jour pour toutes les entreprises de ce navigateur. Les stories publiées avant cette action expireront.','confirm-advance','','Avancer de 24 heures');
      if(action==='confirm-advance'){mutate(()=>Demo.advanceHours(24));closeModal();render();notify('Horloge avancée de 24 heures. Les stories ont expiré.');}
      if(action==='reset')confirmModal('Repartir de la démonstration initiale ?','Cette action efface les personnalisations, invitations, stories et activités créées dans ce navigateur, pour toutes les entreprises. Vous retrouverez les comptes et données de départ.','confirm-reset','','Réinitialiser',true);
      if(action==='confirm-reset'){mutate(()=>Demo.reset());closeModal();location.href='./index.html';}
    }catch(error){notify(error.message||'Cette action n’a pas pu aboutir.',true);}
  });
  document.addEventListener('input',e=>{
    if(e.target.matches('[data-brand]')){brandDraft[e.target.dataset.brand]=e.target.value;if(['color','accent'].includes(e.target.dataset.brand)&&/^#[a-f\d]{6}$/i.test(e.target.value))document.getElementById(e.target.dataset.brand+'-picker').value=e.target.value;updatePreview();}
    if(e.target.matches('[data-color]')){const key=e.target.dataset.color;brandDraft[key]=e.target.value;document.getElementById(key+'-hex').value=e.target.value;updatePreview();}
    if(e.target.matches('[data-team-index]'))teamDraft[Number(e.target.dataset.teamIndex)]=e.target.value;
    if(e.target.id==='people-search'){peopleSearch=e.target.value;document.getElementById('people-table').innerHTML=peopleTable();}
    if(e.target.closest('#campaign-form')&&['budgetEuros','startDate'].includes(e.target.name))refreshCampaignPreview();
  });
  document.addEventListener('change',async e=>{
    try {
      if(e.target.id==='logo-file'){await importLogo(e.target.files[0]);e.target.value='';}
      if(e.target.id==='people-filter'){peopleFilter=e.target.value;document.getElementById('people-table').innerHTML=peopleTable();}
      if(e.target.id==='org-selector'){selectOrg(e.target.value);peopleSearch='';peopleFilter='all';render();}
      if(e.target.id==='catalogue-filter'){catalogueFilter=e.target.value;render();}
      if(e.target.id==='association-logo-file'){await readAssociationLogo(e.target.files[0]);e.target.value='';}
      if(e.target.id==='campaign-association'){
        const select=document.getElementById('campaign-mission'),missions=Platform.catalog().missions.filter(m=>m.associationId===e.target.value);
        select.innerHTML=`<option value="">${missions.length?'Choisir une mission':e.target.value?'Aucune mission disponible':'Choisissez d’abord une association'}</option>`+missions.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');select.disabled=!missions.length;
      }
      if(e.target.closest('#campaign-form')&&e.target.id!=='replace-campaign')refreshCampaignPreview();
    }catch(error){notify(error.message,true);}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!['branding-form','invite-form','teams-form','create-org-form'].includes(form.id))return;e.preventDefault();
    try {
      if(form.id==='branding-form'){
        const draft={name:brandDraft.name.trim(),shortName:brandDraft.shortName.trim(),program:brandDraft.program.trim(),color:brandDraft.color,accent:brandDraft.accent,logo:brandDraft.logo};
        if(!draft.name||!draft.shortName||!draft.program)throw new Error('Renseignez le nom de l’entreprise, le nom court et le programme.');
        if(!/^#[a-f\d]{6}$/i.test(draft.color)||!/^#[a-f\d]{6}$/i.test(draft.accent))throw new Error('Les couleurs doivent utiliser le format #1543B7.');
        mutate(()=>Demo.updateOrg(activeOrg().id,draft));render();notify('Identité enregistrée. Votre application est à jour.');
      }
      if(form.id==='teams-form'){
        const teams=teamDraft.map(t=>t.trim());if(!teams.length||teams.some(t=>!t))throw new Error('Donnez un nom à chaque équipe et conservez au moins une équipe.');
        if(new Set(teams.map(t=>t.toLocaleLowerCase('fr'))).size!==teams.length)throw new Error('Chaque équipe doit avoir un nom différent.');
        const used=members().map(u=>u.team).filter(Boolean);if(used.some(t=>!teams.includes(t)))throw new Error('Une équipe utilisée par un collaborateur ne peut pas être supprimée ou renommée.');
        mutate(()=>Demo.updateOrg(activeOrg().id,{teams}));render();notify('Équipes enregistrées.');
      }
      if(form.id==='invite-form'){
        const data=Object.fromEntries(new FormData(form));data.name=data.name.trim();data.email=data.email.trim().toLowerCase();if(!data.name)throw new Error('Renseignez le prénom et le nom.');
        const result=mutate(()=>Demo.invite(activeOrg().id,data));render();
        showModal('Votre invitation est prête.',`<div class="success-mark">${icon('check')}</div><h3>${esc(result.user.name)} pourra rejoindre votre collectif.</h3><p class="small muted" style="margin-top:10px">Partagez ce lien avec ${esc(result.user.email)}. Pour le tester, déconnectez-vous puis ouvrez-le dans ce même navigateur.</p><div class="invite-url"><input id="created-invite-url" value="${esc(inviteUrl(result.invite.token))}" readonly aria-label="Lien d’invitation"><button class="button primary" data-action="copy-invite" data-token="${esc(result.invite.token)}">${icon('copy')} Copier</button></div><p class="small muted" style="margin-top:12px">Valable jusqu’au ${date(result.invite.expiresAt)} · Aucun e-mail envoyé.</p>`,`<button class="button" data-action="close-modal">Terminer</button>`);
      }
      if(form.id==='create-org-form'){
        const data=Object.fromEntries(new FormData(form));data.teams=data.teams.split(',').map(team=>team.trim()).filter(Boolean);
        const result=mutate(()=>Demo.createOrg(data));selectOrg(result.org.id);page='branding';history.replaceState(null,'','#branding');render();
        showModal('Votre nouvel espace est prêt.',`<div class="success-mark">${icon('check')}</div><h3>${esc(result.org.name)} rejoint Moov’On.</h3><p class="small muted" style="margin-top:12px">Personnalisez son logo, puis invitez les collaborateurs. Le premier compte administrateur est prêt à être utilisé depuis l’écran de connexion.</p><div class="invite-url"><input value="${esc(result.user.email)}" readonly aria-label="E-mail administrateur"><button class="button primary" data-action="copy" data-value="${esc(result.user.email)}">${icon('copy')} Copier</button></div>`,`<button class="button primary" data-action="close-modal">Personnaliser l’espace</button>`);
      }
    }catch(error){if(['invite-form','create-org-form'].includes(form.id)){document.getElementById(form.id==='invite-form'?'invite-error':'create-org-error').innerHTML=`<div class="form-error" role="alert">${esc(error.message)}</div>`;}else notify(error.message,true);}
  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!['campaign-form','association-form','mission-form','rules-form'].includes(form.id))return;e.preventDefault();
    const data=Object.fromEntries(new FormData(form));
    try {
      if(!current()||!Demo.canAdmin())throw new Error('Reconnectez-vous avec un compte administrateur.');
      if(form.id==='campaign-form'){
        mutate(()=>Platform.createCampaign({orgId:activeOrg().id,associationId:data.associationId,missionId:data.missionId,budgetEuros:Number(data.budgetEuros),period:data.period,startDate:data.startDate,replaceActive:data.replaceActive==='on'}));
        closeModal();goPage('campaigns');notify('Campagne créée. Votre application et le suivi sont à jour.');
      }
      if(form.id==='association-form'){
        const result=mutate(()=>Platform.saveAssociation({...associationDraft,...data}));catalogueFilter=result.id;closeModal();render();notify('Association enregistrée dans le catalogue.');
      }
      if(form.id==='mission-form'){
        mutate(()=>Platform.saveMission({...data,id:form.dataset.id||undefined,unitCostEuros:Number(data.unitCostEuros),goalEuros:Number(data.goalEuros)}));closeModal();render();notify('Mission enregistrée. Les entreprises peuvent la sélectionner.');
      }
      if(form.id==='rules-form'){
        const rules=Platform.rules();Object.keys(rules.sports).forEach((sport,i)=>{rules.sports[sport].pointsPerMeter=Number(data['sport-points-'+i]);rules.sports[sport].referenceSpeedKmh=Number(data['sport-speed-'+i]);});
        rules.bonusTiers=rules.bonusTiers.map((tier,i)=>({maxRatio:tier.maxRatio===null?null:Number(data['tier-ratio-'+i]),bonusPct:Number(data['tier-bonus-'+i])}));rules.maxBonusPct=Number(data.maxBonusPct);
        Object.keys(rules.forecast).forEach(key=>{rules.forecast[key]=Number(data['forecast-'+key]);});mutate(()=>Platform.updateRules(rules));render();notify('Règles enregistrées. Elles s’appliquent aux prochaines activités.');
      }
    }catch(error){const target=document.getElementById(form.id.replace('-form','-error'));if(target){target.innerHTML=`<div class="form-error" role="alert">${esc(error.message||'Vérifiez les informations saisies.')}</div>`;target.scrollIntoView?.({block:'nearest',behavior:'smooth'});}else notify(error.message,true);}
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'){closeModal();document.getElementById('sidebar')?.classList.remove('mobile-open');}
    if(e.key==='Tab'&&modalRoot.firstChild){const items=[...modalRoot.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  });
  window.addEventListener('hashchange',()=>{if(Object.hasOwn(titles,location.hash.slice(1))){page=location.hash.slice(1);render();}});
  window.addEventListener('storage',e=>{if(e.key?.startsWith('moovon:app:v2:')&&page==='overview')render(false);});
  function onDataChange(event) {
    if(mutating)return;
    try {
      const session=current(),identity=session?[session.user.id,session.user.role,session.org.id].join(':'):'';
      if(event.type==='reset'||!session||!Demo.canAdmin()||identity!==renderedIdentity){closeModal();render();return;}
      // A story or activity from another tab must not discard an administrator’s form.
      if(modalRoot.firstChild||['branding','teams','rules'].includes(page))return;
      render();
    }catch(error){notify(error.message,true);}
  }
  try {
    if(!window.Demo||!window.Platform||!window.Energy)throw new Error('Le service de démonstration est indisponible. Rechargez cette page depuis le serveur local.');
    render();Platform.onChange(onDataChange);Demo.onChange(onDataChange);
    setInterval(()=>{if(current()&&Demo.canAdmin()&&page==='moderation'&&!modalRoot.firstChild)render(false);},60000);
  }catch(error){protectedPage(error.message);}
})();
